package com.company.platform.analytics.application;
import java.nio.charset.StandardCharsets;import java.util.*;import java.util.stream.Collectors;import java.util.zip.*;import org.springframework.stereotype.Service;
@Service public class ExportService{private final ReportEngineService reports;public ExportService(ReportEngineService r){reports=r;}public byte[] csv(String report,String from,String to){List<Map<String,Object>> rows=rows(report,from,to);if(rows.isEmpty())return "".getBytes(StandardCharsets.UTF_8);List<String> h=new ArrayList<>(rows.get(0).keySet());StringBuilder b=new StringBuilder(h.stream().map(this::quote).collect(Collectors.joining(","))).append('\n');for(Map<String,Object> row:rows)b.append(h.stream().map(k->quote(String.valueOf(row.getOrDefault(k,"")))).collect(Collectors.joining(","))).append('\n');return b.toString().getBytes(StandardCharsets.UTF_8);}public byte[] xlsx(String report,String from,String to){String csv=new String(csv(report,from,to),StandardCharsets.UTF_8);String sheet="<worksheet xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\"><sheetData><row><c t=\"inlineStr\"><is><t>"+xml(csv.replace("\n"," | "))+"</t></is></c></row></sheetData></worksheet>";try{java.io.ByteArrayOutputStream out=new java.io.ByteArrayOutputStream();try(ZipOutputStream z=new ZipOutputStream(out)){z.putNextEntry(new ZipEntry("[Content_Types].xml"));z.write("<?xml version=\"1.0\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Override PartName=\"/xl/worksheets/sheet1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/></Types>".getBytes());z.closeEntry();z.putNextEntry(new ZipEntry("xl/worksheets/sheet1.xml"));z.write(sheet.getBytes());z.closeEntry();}return out.toByteArray();}catch(java.io.IOException e){throw new IllegalStateException("xlsx export failed",e);}}public byte[] pdf(String report,String from,String to){String text=new String(csv(report,from,to),StandardCharsets.UTF_8).replace("(","\\(").replace(")","\\)").replace("\n","\\n");String body="BT /F1 9 Tf 40 760 Td ("+text+ ") Tj ET";String pdf="%PDF-1.4\n1 0 obj<< /Type /Catalog /Pages 2 0 R>>endobj\n2 0 obj<< /Type /Pages /Kids [3 0 R] /Count 1>>endobj\n3 0 obj<< /Type /Page /Parent 2 0 R /MediaBox [0 0 612 792] /Contents 4 0 R /Resources<< /Font<< /F1 5 0 R>>>>>>endobj\n4 0 obj<< /Length "+body.length()+">>stream\n"+body+"\nendstream endobj\n5 0 obj<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica>>endobj\ntrailer<< /Root 1 0 R>>\n%%EOF";return pdf.getBytes(StandardCharsets.US_ASCII);}private List<Map<String,Object>> rows(String r,String f,String t){return switch(r){case "sales"->reports.sales(f,t);case "orders"->reports.orders(f,t);case "payments"->reports.payments(f,t);case "refunds"->reports.refunds(f,t);case "inventory"->reports.inventory();case "fulfillment"->reports.fulfillment();default->throw new IllegalArgumentException("unknown report");};}private String quote(String s){return "\""+s.replace("\"","\"\"")+"\"";}private String xml(String s){return s.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;");}}
